from scipy.optimize import least_squares
cands={
 'v':lambda p: p[4]*v,
 'x':lambda p: p[4]*x,
 'const':lambda p: p[4]+0*x,
 'xv':lambda p: p[4]*x*v,
 'v2':lambda p: p[4]*v*v,
 'x2':lambda p: p[4]*x*x,
 'x_sqrtv':lambda p: p[4]*x*np.sqrt(v),
 'v^1.5':lambda p: p[4]*v**1.5,
 'tv':lambda p: p[4]*t*v,
}
def mk(f):
    def m(p):
        return p[0]*(x/(1+p[1]*x))*np.sqrt(v)+p[2]*np.exp(-p[3]*t**2)+f(p)
    return m
for k,f in cands.items():
    m=mk(f); bestc=None
    for s in range(40):
        rs=np.random.RandomState(s)
        p0=rs.uniform(-2,2,5); p0[1]=abs(p0[1]); p0[3]=abs(p0[3])
        try:
